import { sql } from "drizzle-orm";
import {
  bigint,
  bigserial,
  boolean,
  customType,
  date,
  index,
  integer,
  jsonb,
  numeric,
  pgTable,
  text,
  timestamp,
  uniqueIndex,
} from "drizzle-orm/pg-core";

/**
 * TokenIQ data model. Conventions:
 * - ids are text UUIDs generated by the app (Better Auth also uses text ids)
 * - timestamps are timestamptz; calendar due dates are `date`
 * - USD values are numeric(38,18) carried as decimal strings; token amounts are numeric(78,0) raw units
 * - nothing financial is stored as a float
 * - audit_events, approvals, safe_signatures and policy versions are append-only
 * - every organization-owned row carries organization_id and every query filters by it
 */

const id = () => text("id").primaryKey().$defaultFn(() => crypto.randomUUID());
const createdAt = () => timestamp("created_at", { withTimezone: true }).notNull().defaultNow();
const updatedAt = () => timestamp("updated_at", { withTimezone: true }).notNull().defaultNow().$onUpdate(() => new Date());
const usd = (name: string) => numeric(name, { precision: 38, scale: 18 });
const raw = (name: string) => numeric(name, { precision: 78, scale: 0 });
const orgId = () => text("organization_id").notNull().references(() => organizations.id, { onDelete: "cascade" });

const bytea = customType<{ data: Buffer; driverData: Buffer }>({ dataType: () => "bytea" });

// ---------------------------------------------------------------------------
// Identity — Better Auth core tables

export const users = pgTable(
  "users",
  {
    id: text("id").primaryKey(),
    name: text("name").notNull(),
    email: text("email").notNull(),
    emailVerified: boolean("email_verified").notNull().default(false),
    image: text("image"),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [uniqueIndex("users_email_uq").on(sql`lower(${t.email})`)],
);

export const sessions = pgTable(
  "sessions",
  {
    id: text("id").primaryKey(),
    expiresAt: timestamp("expires_at", { withTimezone: true }).notNull(),
    token: text("token").notNull(),
    ipAddress: text("ip_address"),
    userAgent: text("user_agent"),
    userId: text("user_id").notNull().references(() => users.id, { onDelete: "cascade" }),
    activeOrganizationId: text("active_organization_id"),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [uniqueIndex("sessions_token_uq").on(t.token), index("sessions_user_idx").on(t.userId)],
);

export const accounts = pgTable(
  "accounts",
  {
    id: text("id").primaryKey(),
    accountId: text("account_id").notNull(),
    providerId: text("provider_id").notNull(),
    userId: text("user_id").notNull().references(() => users.id, { onDelete: "cascade" }),
    accessToken: text("access_token"),
    refreshToken: text("refresh_token"),
    idToken: text("id_token"),
    accessTokenExpiresAt: timestamp("access_token_expires_at", { withTimezone: true }),
    refreshTokenExpiresAt: timestamp("refresh_token_expires_at", { withTimezone: true }),
    scope: text("scope"),
    password: text("password"),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [index("accounts_user_idx").on(t.userId)],
);

export const verifications = pgTable(
  "verifications",
  {
    id: text("id").primaryKey(),
    identifier: text("identifier").notNull(),
    value: text("value").notNull(),
    expiresAt: timestamp("expires_at", { withTimezone: true }).notNull(),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [index("verifications_identifier_idx").on(t.identifier)],
);

/** WebAuthn credentials (Better Auth passkey plugin). */
export const passkeys = pgTable(
  "passkeys",
  {
    id: text("id").primaryKey(),
    name: text("name"),
    publicKey: text("public_key").notNull(),
    userId: text("user_id").notNull().references(() => users.id, { onDelete: "cascade" }),
    credentialID: text("credential_id").notNull(),
    counter: integer("counter").notNull(),
    deviceType: text("device_type").notNull(),
    backedUp: boolean("backed_up").notNull(),
    transports: text("transports"),
    aaguid: text("aaguid"),
    createdAt: timestamp("created_at", { withTimezone: true }),
  },
  (t) => [index("passkeys_user_idx").on(t.userId), uniqueIndex("passkeys_credential_uq").on(t.credentialID)],
);

/** Wallets used to sign in with Ethereum (Better Auth SIWE plugin). Sign-in only; not treasury verification. */
export const walletAddresses = pgTable(
  "wallet_addresses",
  {
    id: text("id").primaryKey(),
    userId: text("user_id").notNull().references(() => users.id, { onDelete: "cascade" }),
    address: text("address").notNull(),
    chainId: integer("chain_id").notNull(),
    isPrimary: boolean("is_primary").default(false),
    createdAt: createdAt(),
  },
  (t) => [index("wallet_addresses_user_idx").on(t.userId), uniqueIndex("wallet_addresses_address_chain_uq").on(sql`lower(${t.address})`, t.chainId)],
);

// ---------------------------------------------------------------------------
// Organizations — Better Auth organization plugin tables

export const organizations = pgTable(
  "organizations",
  {
    id: text("id").primaryKey(),
    name: text("name").notNull(),
    slug: text("slug").notNull(),
    logo: text("logo"),
    metadata: text("metadata"),
    createdAt: createdAt(),
  },
  (t) => [uniqueIndex("organizations_slug_uq").on(t.slug)],
);

/** Roles: owner | admin | finance | approver | viewer (see @tokeniq/core approvals). */
export const members = pgTable(
  "members",
  {
    id: text("id").primaryKey(),
    organizationId: orgId(),
    userId: text("user_id").notNull().references(() => users.id, { onDelete: "cascade" }),
    role: text("role").notNull().default("viewer"),
    createdAt: createdAt(),
  },
  (t) => [uniqueIndex("members_org_user_uq").on(t.organizationId, t.userId), index("members_user_idx").on(t.userId)],
);

export const invitations = pgTable(
  "invitations",
  {
    id: text("id").primaryKey(),
    organizationId: orgId(),
    email: text("email").notNull(),
    role: text("role"),
    status: text("status").notNull().default("pending"),
    expiresAt: timestamp("expires_at", { withTimezone: true }).notNull(),
    inviterId: text("inviter_id").notNull().references(() => users.id, { onDelete: "cascade" }),
    createdAt: createdAt(),
  },
  (t) => [index("invitations_org_idx").on(t.organizationId), index("invitations_email_idx").on(sql`lower(${t.email})`)],
);

// ---------------------------------------------------------------------------
// Organization profile and onboarding

export const orgProfiles = pgTable("org_profiles", {
  organizationId: text("organization_id")
    .primaryKey()
    .references(() => organizations.id, { onDelete: "cascade" }),
  purpose: text("purpose"),
  reportingCurrency: text("reporting_currency").notNull().default("USD"),
  /** Clearly labelled simulation workspace: all data is synthetic and nothing can execute. */
  isSample: boolean("is_sample").notNull().default(false),
  /** Completed onboarding steps, e.g. ["organization","treasury","obligations","policy"]. */
  onboardingSteps: text("onboarding_steps").array().notNull().default(sql`'{}'::text[]`),
  onboardingCompletedAt: timestamp("onboarding_completed_at", { withTimezone: true }),
  createdAt: createdAt(),
  updatedAt: updatedAt(),
});

// ---------------------------------------------------------------------------
// Policies — append-only versions. The current policy is the highest version.

export const policyVersions = pgTable(
  "policy_versions",
  {
    id: id(),
    organizationId: orgId(),
    kind: text("kind").notNull(), // treasury | approval
    version: integer("version").notNull(),
    body: jsonb("body").notNull(),
    reason: text("reason"),
    createdBy: text("created_by").references(() => users.id, { onDelete: "set null" }),
    createdAt: createdAt(),
  },
  (t) => [uniqueIndex("policy_versions_org_kind_version_uq").on(t.organizationId, t.kind, t.version)],
);

// ---------------------------------------------------------------------------
// Treasury accounts and observed on-chain state

export const treasuryAccounts = pgTable(
  "treasury_accounts",
  {
    id: id(),
    organizationId: orgId(),
    chainId: integer("chain_id").notNull(),
    /** Lower-cased 0x address. */
    address: text("address").notNull(),
    kind: text("kind").notNull(), // safe | eoa | contract
    label: text("label").notNull(),
    purpose: text("purpose").notNull().default("operating"), // operating | reserve | grants | other
    includeInTreasury: boolean("include_in_treasury").notNull().default(true),
    verifiedAt: timestamp("verified_at", { withTimezone: true }),
    verifiedBy: text("verified_by").references(() => users.id, { onDelete: "set null" }),
    /** siwe_owner (signed by a Safe owner) | siwe_address (signed by the address) | sample */
    verificationMethod: text("verification_method"),
    /** The signer address that proved control (for Safes, an owner). */
    verificationSigner: text("verification_signer"),
    safeOwners: text("safe_owners").array(),
    safeThreshold: integer("safe_threshold"),
    safeVersion: text("safe_version"),
    safeNonce: bigint("safe_nonce", { mode: "bigint" }),
    safeGuard: text("safe_guard"),
    safeModules: text("safe_modules").array(),
    lastSyncedAt: timestamp("last_synced_at", { withTimezone: true }),
    lastSyncError: text("last_sync_error"),
    createdBy: text("created_by").references(() => users.id, { onDelete: "set null" }),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
    archivedAt: timestamp("archived_at", { withTimezone: true }),
  },
  (t) => [uniqueIndex("treasury_accounts_org_chain_address_uq").on(t.organizationId, t.chainId, t.address), index("treasury_accounts_org_idx").on(t.organizationId)],
);

/** One-time challenges for proving control of an address. */
export const addressChallenges = pgTable(
  "address_challenges",
  {
    id: id(),
    organizationId: orgId(),
    userId: text("user_id").notNull().references(() => users.id, { onDelete: "cascade" }),
    accountId: text("account_id").references(() => treasuryAccounts.id, { onDelete: "cascade" }),
    chainId: integer("chain_id").notNull(),
    address: text("address").notNull(),
    nonce: text("nonce").notNull(),
    message: text("message").notNull(),
    expiresAt: timestamp("expires_at", { withTimezone: true }).notNull(),
    usedAt: timestamp("used_at", { withTimezone: true }),
    createdAt: createdAt(),
  },
  (t) => [uniqueIndex("address_challenges_nonce_uq").on(t.nonce)],
);

/** Balance of one asset in one account at one block. Idempotent per (account, asset, block). */
export const balanceSnapshots = pgTable(
  "balance_snapshots",
  {
    id: bigserial("id", { mode: "bigint" }).primaryKey(),
    organizationId: orgId(),
    accountId: text("account_id").notNull().references(() => treasuryAccounts.id, { onDelete: "cascade" }),
    chainId: integer("chain_id").notNull(),
    assetAddress: text("asset_address").notNull(),
    assetSymbol: text("asset_symbol").notNull(),
    rawBalance: raw("raw_balance").notNull(),
    blockNumber: bigint("block_number", { mode: "bigint" }).notNull(),
    blockHash: text("block_hash"),
    observedAt: timestamp("observed_at", { withTimezone: true }).notNull(),
  },
  (t) => [
    uniqueIndex("balance_snapshots_account_asset_block_uq").on(t.accountId, t.assetAddress, t.blockNumber),
    index("balance_snapshots_latest_idx").on(t.accountId, t.assetAddress, t.observedAt),
    index("balance_snapshots_org_time_idx").on(t.organizationId, t.observedAt),
  ],
);

/** Value of a protocol position (e.g. ERC-4626 shares) at one block. */
export const positionSnapshots = pgTable(
  "position_snapshots",
  {
    id: bigserial("id", { mode: "bigint" }).primaryKey(),
    organizationId: orgId(),
    accountId: text("account_id").notNull().references(() => treasuryAccounts.id, { onDelete: "cascade" }),
    chainId: integer("chain_id").notNull(),
    protocol: text("protocol").notNull(),
    venueId: text("venue_id").notNull(),
    venueAddress: text("venue_address").notNull(),
    venueName: text("venue_name").notNull(),
    assetAddress: text("asset_address").notNull(),
    assetSymbol: text("asset_symbol").notNull(),
    sharesRaw: raw("shares_raw").notNull(),
    assetsRaw: raw("assets_raw").notNull(),
    withdrawableRaw: raw("withdrawable_raw"),
    blockNumber: bigint("block_number", { mode: "bigint" }).notNull(),
    observedAt: timestamp("observed_at", { withTimezone: true }).notNull(),
  },
  (t) => [
    uniqueIndex("position_snapshots_account_venue_block_uq").on(t.accountId, t.venueId, t.blockNumber),
    index("position_snapshots_latest_idx").on(t.accountId, t.venueId, t.observedAt),
  ],
);

/** Oracle observations (Chainlink answers with their own updatedAt). */
export const priceObservations = pgTable(
  "price_observations",
  {
    id: bigserial("id", { mode: "bigint" }).primaryKey(),
    chainId: integer("chain_id").notNull(),
    feed: text("feed").notNull(),
    pair: text("pair").notNull(),
    answer: raw("answer").notNull(),
    decimals: integer("decimals").notNull(),
    roundId: text("round_id").notNull(),
    updatedAt: timestamp("updated_at", { withTimezone: true }).notNull(),
    observedAt: timestamp("observed_at", { withTimezone: true }).notNull().defaultNow(),
    source: text("source").notNull().default("chainlink"),
  },
  (t) => [uniqueIndex("price_observations_feed_round_uq").on(t.chainId, t.feed, t.roundId), index("price_observations_latest_idx").on(t.chainId, t.feed, t.observedAt)],
);

// ---------------------------------------------------------------------------
// Obligations and payments

export const obligations = pgTable(
  "obligations",
  {
    id: id(),
    organizationId: orgId(),
    title: text("title").notNull(),
    category: text("category").notNull(),
    direction: text("direction").notNull().default("outflow"),
    amount: usd("amount").notNull(),
    currency: text("currency").notNull().default("USD"),
    firstDueDate: date("first_due_date", { mode: "string" }).notNull(),
    recurrence: jsonb("recurrence").notNull(),
    certainty: text("certainty").notNull(),
    priority: text("priority").notNull().default("normal"),
    status: text("status").notNull().default("active"),
    trackFrom: date("track_from", { mode: "string" }).notNull(),
    counterparty: text("counterparty"),
    recipientAddress: text("recipient_address"),
    recipientChainId: integer("recipient_chain_id"),
    paymentAsset: text("payment_asset"),
    invoiceNumber: text("invoice_number"),
    notes: text("notes"),
    createdBy: text("created_by").references(() => users.id, { onDelete: "set null" }),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [index("obligations_org_idx").on(t.organizationId, t.status)],
);

export const obligationDocuments = pgTable(
  "obligation_documents",
  {
    id: id(),
    organizationId: orgId(),
    obligationId: text("obligation_id").notNull().references(() => obligations.id, { onDelete: "cascade" }),
    filename: text("filename").notNull(),
    contentType: text("content_type").notNull(),
    sizeBytes: integer("size_bytes").notNull(),
    sha256: text("sha256").notNull(),
    content: bytea("content").notNull(),
    uploadedBy: text("uploaded_by").references(() => users.id, { onDelete: "set null" }),
    createdAt: createdAt(),
  },
  (t) => [index("obligation_documents_obligation_idx").on(t.obligationId)],
);

/**
 * Settlement of one obligation occurrence.
 * status: paid_unverified (a member says it was paid) | paid_verified (TokenIQ matched an on-chain transfer) | skipped
 */
export const payments = pgTable(
  "payments",
  {
    id: id(),
    organizationId: orgId(),
    obligationId: text("obligation_id").notNull().references(() => obligations.id, { onDelete: "cascade" }),
    dueDate: date("due_date", { mode: "string" }).notNull(),
    status: text("status").notNull(),
    amount: usd("amount"),
    assetSymbol: text("asset_symbol"),
    tokenAmountRaw: raw("token_amount_raw"),
    chainId: integer("chain_id"),
    txHash: text("tx_hash"),
    /** Log index of the matched Transfer; one on-chain transfer can settle only one occurrence. */
    transferLogIndex: integer("transfer_log_index"),
    fromAddress: text("from_address"),
    toAddress: text("to_address"),
    verifiedAt: timestamp("verified_at", { withTimezone: true }),
    verification: jsonb("verification"),
    proposalId: text("proposal_id"),
    note: text("note"),
    recordedBy: text("recorded_by").references(() => users.id, { onDelete: "set null" }),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [
    uniqueIndex("payments_obligation_due_uq").on(t.obligationId, t.dueDate),
    index("payments_org_idx").on(t.organizationId, t.createdAt),
    uniqueIndex("payments_transfer_uq")
      .on(t.organizationId, t.chainId, t.txHash, t.transferLogIndex)
      .where(sql`${t.transferLogIndex} is not null`),
  ],
);

// ---------------------------------------------------------------------------
// Opportunities (global, not organization-owned)

export const opportunities = pgTable(
  "opportunities",
  {
    id: text("id").primaryKey(),
    protocol: text("protocol").notNull(),
    chainId: integer("chain_id").notNull(),
    address: text("address").notNull(),
    name: text("name").notNull(),
    assetSymbol: text("asset_symbol").notNull(),
    listed: boolean("listed").notNull().default(false),
    data: jsonb("data").notNull(),
    fetchedAt: timestamp("fetched_at", { withTimezone: true }).notNull(),
    updatedAt: updatedAt(),
  },
  (t) => [index("opportunities_chain_asset_idx").on(t.chainId, t.assetSymbol)],
);

export const opportunitySnapshots = pgTable(
  "opportunity_snapshots",
  {
    id: bigserial("id", { mode: "bigint" }).primaryKey(),
    opportunityId: text("opportunity_id").notNull(),
    netApyBps: integer("net_apy_bps").notNull(),
    tvlUsd: usd("tvl_usd").notNull(),
    liquidityUsd: usd("liquidity_usd").notNull(),
    fetchedAt: timestamp("fetched_at", { withTimezone: true }).notNull(),
  },
  (t) => [uniqueIndex("opportunity_snapshots_opp_time_uq").on(t.opportunityId, t.fetchedAt)],
);

// ---------------------------------------------------------------------------
// Recommendations, proposals, approvals, signatures, executions

export const recommendations = pgTable(
  "recommendations",
  {
    id: id(),
    organizationId: orgId(),
    fingerprint: text("fingerprint").notNull(),
    kind: text("kind").notNull(),
    status: text("status").notNull().default("open"), // open | accepted | dismissed | superseded
    title: text("title").notNull(),
    payload: jsonb("payload").notNull(),
    createdAt: createdAt(),
    resolvedAt: timestamp("resolved_at", { withTimezone: true }),
    resolvedBy: text("resolved_by").references(() => users.id, { onDelete: "set null" }),
    resolution: text("resolution"),
  },
  (t) => [uniqueIndex("recommendations_org_fingerprint_uq").on(t.organizationId, t.fingerprint), index("recommendations_org_status_idx").on(t.organizationId, t.status)],
);

/**
 * A structured action moving through: pending_approval → approved → awaiting_signatures
 * → ready_to_execute → submitted → executed | failed, or rejected | expired | cancelled | stale.
 */
export const proposals = pgTable(
  "proposals",
  {
    id: id(),
    organizationId: orgId(),
    recommendationId: text("recommendation_id").references(() => recommendations.id, { onDelete: "set null" }),
    kind: text("kind").notNull(), // allocate | withdraw | payment
    title: text("title").notNull(),
    status: text("status").notNull(),
    action: jsonb("action").notNull(),
    amountUsd: usd("amount_usd").notNull(),
    accountId: text("account_id").notNull().references(() => treasuryAccounts.id, { onDelete: "restrict" }),
    chainId: integer("chain_id").notNull(),
    validation: jsonb("validation").notNull(),
    simulation: jsonb("simulation"),
    safeTx: jsonb("safe_tx"),
    safeTxHash: text("safe_tx_hash"),
    proposerId: text("proposer_id").notNull().references(() => users.id, { onDelete: "restrict" }),
    idempotencyKey: text("idempotency_key").notNull(),
    expiresAt: timestamp("expires_at", { withTimezone: true }).notNull(),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [
    uniqueIndex("proposals_org_idempotency_uq").on(t.organizationId, t.idempotencyKey),
    index("proposals_org_status_idx").on(t.organizationId, t.status),
    uniqueIndex("proposals_safe_tx_hash_uq").on(t.safeTxHash),
  ],
);

/** Internal approval decisions. Append-only; the latest decision per member counts. */
export const approvals = pgTable(
  "approvals",
  {
    id: id(),
    organizationId: orgId(),
    proposalId: text("proposal_id").notNull().references(() => proposals.id, { onDelete: "cascade" }),
    userId: text("user_id").notNull().references(() => users.id, { onDelete: "restrict" }),
    role: text("role").notNull(),
    decision: text("decision").notNull(), // approve | reject
    comment: text("comment"),
    createdAt: createdAt(),
  },
  // One decision per member per proposal, enforced by the database as well as the route.
  (t) => [index("approvals_proposal_idx").on(t.proposalId), uniqueIndex("approvals_proposal_user_uq").on(t.proposalId, t.userId)],
);

export const proposalComments = pgTable(
  "proposal_comments",
  {
    id: id(),
    organizationId: orgId(),
    proposalId: text("proposal_id").notNull().references(() => proposals.id, { onDelete: "cascade" }),
    userId: text("user_id").notNull().references(() => users.id, { onDelete: "restrict" }),
    body: text("body").notNull(),
    createdAt: createdAt(),
  },
  (t) => [index("proposal_comments_proposal_idx").on(t.proposalId)],
);

/** EIP-712 signatures over a Safe transaction hash, verified server-side against current Safe owners. */
export const safeSignatures = pgTable(
  "safe_signatures",
  {
    id: id(),
    organizationId: orgId(),
    proposalId: text("proposal_id").notNull().references(() => proposals.id, { onDelete: "cascade" }),
    safeTxHash: text("safe_tx_hash").notNull(),
    signer: text("signer").notNull(),
    signature: text("signature").notNull(),
    submittedBy: text("submitted_by").references(() => users.id, { onDelete: "set null" }),
    createdAt: createdAt(),
  },
  (t) => [uniqueIndex("safe_signatures_tx_signer_uq").on(t.safeTxHash, t.signer)],
);

export const executions = pgTable(
  "executions",
  {
    id: id(),
    organizationId: orgId(),
    proposalId: text("proposal_id").notNull().references(() => proposals.id, { onDelete: "cascade" }),
    chainId: integer("chain_id").notNull(),
    txHash: text("tx_hash").notNull(),
    status: text("status").notNull(), // submitted | confirmed | reverted | replaced | dropped
    submittedBy: text("submitted_by").references(() => users.id, { onDelete: "set null" }),
    submittedAt: timestamp("submitted_at", { withTimezone: true }).notNull().defaultNow(),
    blockNumber: bigint("block_number", { mode: "bigint" }),
    gasUsed: raw("gas_used"),
    effectiveGasPrice: raw("effective_gas_price"),
    /** Safe emits ExecutionSuccess/ExecutionFailure; a mined tx can still fail inside the Safe. */
    safeSuccess: boolean("safe_success"),
    receipt: jsonb("receipt"),
    reconciledAt: timestamp("reconciled_at", { withTimezone: true }),
    updatedAt: updatedAt(),
  },
  // Unique per proposal, not per chain: a transaction hash is public, so another organization recording it
  // first must not block the real proposal from tracking its own execution.
  (t) => [uniqueIndex("executions_proposal_tx_uq").on(t.proposalId, t.txHash), index("executions_chain_tx_idx").on(t.chainId, t.txHash)],
);

// ---------------------------------------------------------------------------
// Risk, notifications, audit

export const riskAlerts = pgTable(
  "risk_alerts",
  {
    id: id(),
    organizationId: orgId(),
    fingerprint: text("fingerprint").notNull(),
    kind: text("kind").notNull(),
    severity: text("severity").notNull(),
    title: text("title").notNull(),
    condition: text("condition").notNull(),
    evidence: jsonb("evidence").notNull(),
    recommendedAction: text("recommended_action").notNull(),
    ref: text("ref"),
    status: text("status").notNull().default("open"), // open | acknowledged | resolved
    firstSeenAt: timestamp("first_seen_at", { withTimezone: true }).notNull().defaultNow(),
    lastSeenAt: timestamp("last_seen_at", { withTimezone: true }).notNull().defaultNow(),
    acknowledgedAt: timestamp("acknowledged_at", { withTimezone: true }),
    acknowledgedBy: text("acknowledged_by").references(() => users.id, { onDelete: "set null" }),
    resolvedAt: timestamp("resolved_at", { withTimezone: true }),
  },
  (t) => [
    uniqueIndex("risk_alerts_org_fingerprint_active_uq").on(t.organizationId, t.fingerprint).where(sql`${t.status} <> 'resolved'`),
    index("risk_alerts_org_status_idx").on(t.organizationId, t.status),
  ],
);

export const notifications = pgTable(
  "notifications",
  {
    id: id(),
    organizationId: orgId(),
    userId: text("user_id").notNull().references(() => users.id, { onDelete: "cascade" }),
    kind: text("kind").notNull(),
    title: text("title").notNull(),
    body: text("body"),
    link: text("link"),
    dedupeKey: text("dedupe_key"),
    readAt: timestamp("read_at", { withTimezone: true }),
    createdAt: createdAt(),
  },
  (t) => [index("notifications_user_idx").on(t.userId, t.readAt), uniqueIndex("notifications_user_dedupe_uq").on(t.userId, t.dedupeKey)],
);

/** Append-only. A trigger in the migrations rejects UPDATE and DELETE. */
export const auditEvents = pgTable(
  "audit_events",
  {
    id: bigserial("id", { mode: "bigint" }).primaryKey(),
    organizationId: text("organization_id"),
    actorUserId: text("actor_user_id"),
    actorType: text("actor_type").notNull(), // user | system | copilot
    action: text("action").notNull(),
    targetType: text("target_type"),
    targetId: text("target_id"),
    data: jsonb("data"),
    ip: text("ip"),
    userAgent: text("user_agent"),
    createdAt: createdAt(),
  },
  (t) => [index("audit_events_org_time_idx").on(t.organizationId, t.createdAt), index("audit_events_target_idx").on(t.targetType, t.targetId)],
);

// ---------------------------------------------------------------------------
// Operations

export const providerHealth = pgTable("provider_health", {
  provider: text("provider").primaryKey(),
  status: text("status").notNull(), // ok | degraded | down
  lastOkAt: timestamp("last_ok_at", { withTimezone: true }),
  lastErrorAt: timestamp("last_error_at", { withTimezone: true }),
  lastError: text("last_error"),
  latencyMs: integer("latency_ms"),
  consecutiveFailures: integer("consecutive_failures").notNull().default(0),
  updatedAt: updatedAt(),
});

/** Responses to financial write requests, replayed for duplicate Idempotency-Key headers. */
export const idempotencyKeys = pgTable(
  "idempotency_keys",
  {
    key: text("key").notNull(),
    organizationId: text("organization_id").notNull(),
    userId: text("user_id").notNull(),
    route: text("route").notNull(),
    requestHash: text("request_hash").notNull(),
    statusCode: integer("status_code"),
    response: jsonb("response"),
    createdAt: createdAt(),
  },
  (t) => [uniqueIndex("idempotency_keys_uq").on(t.organizationId, t.userId, t.key)],
);

export const copilotThreads = pgTable(
  "copilot_threads",
  {
    id: id(),
    organizationId: orgId(),
    userId: text("user_id").notNull().references(() => users.id, { onDelete: "cascade" }),
    title: text("title").notNull(),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [index("copilot_threads_user_idx").on(t.organizationId, t.userId)],
);

export const copilotMessages = pgTable(
  "copilot_messages",
  {
    id: id(),
    organizationId: orgId(),
    threadId: text("thread_id").notNull().references(() => copilotThreads.id, { onDelete: "cascade" }),
    role: text("role").notNull(), // user | assistant
    content: jsonb("content").notNull(),
    toolCalls: jsonb("tool_calls"),
    model: text("model"),
    inputTokens: integer("input_tokens"),
    outputTokens: integer("output_tokens"),
    createdAt: createdAt(),
  },
  (t) => [index("copilot_messages_thread_idx").on(t.threadId, t.createdAt)],
);
